/* Las calculadoras de Habilidades Base: cada una recibe los valores de sus deslizadores y devuelve tres cifras, a veces una
   gráfica (`graf`, del mismo formato que las de los pasos) y una nota. Usan hbPesos y hbPesosCorto de dashboard.html. */
const HB_CALC = {
  // Reacción (velocidad × tiempo) más frenado (v² ÷ 2μg), contra los tres segundos de distancia a esa velocidad.
  frenado(v) {
    const m = v.vel / 3.6, r = m * v.reac, f = m * m / (2 * v.mu * 9.81), tres = m * 3, tot = r + f, k = x => Math.round(x) + ' m';
    return { cifras: [[k(tot), 'para detenerte por completo'], [k(r), 'recorres antes de tocar el freno'], [k(tres), 'son tus tres segundos de distancia a esa velocidad']],
      graf: { tipo: 'barras', u: 'm', datos: [['Mientras reaccionas', r, k(r)], ['Mientras frenas', f, k(f)], ['Tus tres segundos de distancia', tres, k(tres)]], dest: [0, 1] },
      nota: tot > tres ? 'Parar te toma más que tus tres segundos: esa distancia no es para frenar en seco, es para <b>reaccionar a tiempo</b> si el de adelante frena. Con piso malo o distraído, aléjate más.' : 'Tus tres segundos alcanzan para reaccionar y frenar. Con lluvia, duplica la distancia.' };
  },
  // La cafeína que queda a tu hora de dormir (la de la rutina, por HB_DATO) con su vida media, y la curva hasta la mañana.
  cafeina(v) {
    const dormir = HB_DATO.dormir(), d = (dormir - v.hora + 24) % 24, queda = h => v.mg * Math.pow(0.5, h / v.vida), q = queda(d);
    const reloj = h => { const m = Math.round(((h % 24) + 24) % 24 * 60); return Math.floor(m / 60) + ':' + String(m % 60).padStart(2, '0'); };
    // cada 10 minutos, para que tu hora de dormir caiga justo en un punto; el eje solo nombra las horas pares
    const x = [], s = [], iDormir = Math.round(d * 6);
    for (let i = 0; i <= Math.round((d + 7) * 6); i++) { const t = (v.hora + i / 6) % 24, m = Math.round(t * 60); x.push(m % 120 === 0 ? reloj(t) : ''); s.push(+queda(i / 6).toFixed(1)); }
    const bajo = v.hora + v.vida * Math.log2(v.mg / 25);
    return { cifras: [[Math.round(q) + ' mg', 'siguen en ti a las ' + reloj(dormir) + ', tu hora de dormir'], [Math.round(q / v.mg * 100) + ' %', 'de lo que tomaste'], [reloj(bajo), 'baja de 25 mg, menos que una lata de refresco']],
      graf: { tipo: 'linea', t: 'La cafeína en tu cuerpo, hora por hora', u: 'mg', uy: 'mg', x, xTodas: true, sinTabla: true, series: [{ n: 'Cafeína', v: s }], area: true, marcas: [{ i: iDormir, txt: 'Te acuestas: ' + Math.round(q) + ' mg' }] },
      nota: q >= 45 ? 'Es como <b>acostarte con medio café</b> encima: no te impide dormir, pero te quita sueño profundo. Muévela antes de las 2 o 3 pm.' : q >= 25 ? 'Te acuestas con <b>más de lo que trae una lata de refresco de cola</b>: suficiente para quitarte algo de sueño profundo. Si puedes, adelántala una o dos horas.' : 'A esa hora ya queda poco: así se protege el sueño profundo.' };
  },
  // La prueba del «sí absoluto»: solo es sí si la reacción es un sí claro, el amigo aceptaría y mañana no pesa.
  siabsoluto(v) {
    const si = v.reaccion === 1 && v.amigo >= 0 && v.manana === 1, dudas = [v.reaccion < 1, v.amigo < 1, v.manana < 1].filter(Boolean).length;
    return si ? { cifras: [['Sí', 'acéptalo, y sin culpa'], [dudas + ' de 3', 'pruebas con duda'], ['1', 'compromiso más: agéndalo hoy']], nota: 'Pasa las tres pruebas. Dilo con la misma claridad con la que dirías que no: «cuenta conmigo, ¿qué día?».' }
      : { cifras: [['No', 'es la respuesta'], [dudas + ' de 3', 'pruebas fallaron'], ['24 h', 'como máximo para decirlo']],
        nota: 'Usa la fórmula de tres partes: <b>«Gracias por pensar en mí; esta vez no voy a poder. Que te vaya increíble.»</b> Sin explicación de más: cada razón es algo que negociar.' };
  },
  // Comidas que cambias de pedir a hacer en casa: lo que ahorras a la semana, al mes (4.3 semanas) y al año.
  cocina(v) {
    const sem = (v.fuera - v.casa) * v.n, mes = sem * 4.3, anio = sem * 52;
    return { cifras: [[hbPesos(mes), 'al mes'], [hbPesos(anio), 'al año'], [Math.round((v.fuera - v.casa) / v.fuera * 100) + ' %', 'menos por comida']],
      graf: { tipo: 'barras', datos: [['Pidiendo, al mes', v.fuera * v.n * 4.3, hbPesos(v.fuera * v.n * 4.3)], ['Cocinando, al mes', v.casa * v.n * 4.3, hbPesos(v.casa * v.n * 4.3)]], dest: [1] },
      nota: 'Esos <b>' + hbPesos(anio) + '</b> al año, invertidos en lugar de gastados, son la cuenta del interés compuesto de tu ficha de dinero.' };
  },
  // Con un precio (1 + p) veces más alto, el mismo ingreso sale con 1 / (1 + p) del trabajo.
  precio(v) {
    const p = v.sube / 100, igual = 1 / (1 + p), libre = 1 - igual;
    return { cifras: [[Math.round(libre * 100) + ' %', 'de tus horas o clientes podrías soltar y ganar lo mismo'], [Math.round(v.horas * igual) + ' h', 'al mes te dejan lo que hoy te dejan ' + v.horas + ' h'], ['+' + v.sube + ' %', 'de ingreso si no pierdes a nadie']],
      nota: 'Con el precio ' + v.sube + ' % más alto, <b>' + Math.round(v.horas * libre) + ' horas al mes</b> quedan libres para lo que sí escala: tu plantilla, un curso, un cliente mejor.' };
  },
  // La meta del fondo y cuántos meses tardas en juntarla.
  fondo(v) {
    const meta = v.gasto * v.meses, n = Math.ceil(meta / v.aparta), n3 = Math.ceil(v.gasto * 3 / v.aparta);
    return { cifras: [[hbPesos(meta), 'tu meta: ' + v.meses + ' meses de gasto'], [n + ' meses', 'para llegar apartando ' + hbPesos(v.aparta)], [n3 + ' meses', 'para el primer escalón: 3 meses de gasto']],
      nota: n > 24 ? 'Más de dos años. Empieza por el escalón de 3 meses y sube lo que apartas cada vez que suba tu ingreso.' : 'Ponlo en CETES a 28 días o en una cuenta con rendimiento: que esté disponible en días, no en meses.' };
  },
  // La tarjeta mes a mes: interés de tasa ÷ 12 más su IVA, menos tu pago. Y lo que cambia si pagas $500 más.
  deuda(v) {
    const r = v.tasa / 100 / 12 * 1.16, int0 = v.saldo * r;
    const corre = pago => { let b = v.saldo, m = 0, it = 0; const s = [b]; while (b > 0 && m < 600) { const i = b * r; it += i; b = b + i - pago; m++; s.push(Math.max(0, b)); } return { m, it, s }; };
    if (v.pago <= int0) return { cifras: [['Nunca', 'se termina de pagar con ese pago'], [hbPesos(int0), 'de interés el primer mes, con IVA'], [hbPesos(v.pago), 'lo que pagas: no cubre ni el interés']], nota: 'Con ese pago la deuda no baja. <b>Sube el pago por encima del interés del mes</b> y no vuelvas a usar la tarjeta.' };
    const a = corre(v.pago), b = corre(v.pago + 500), paso = Math.max(1, Math.ceil(a.m / 24)), x = [], s = [];
    for (let m = 0; m <= a.m; m += paso) { x.push(m === 0 ? 'Hoy' : 'Mes ' + m); s.push(Math.round(a.s[m])); }
    if (a.m % paso) { x.push('Mes ' + a.m); s.push(0); }
    return { cifras: [[a.m + ' meses', 'para liquidarla (' + (a.m / 12).toLocaleString('es-MX', { maximumFractionDigits: 1 }) + ' años)'], [hbPesos(a.it), 'de intereses, con IVA'], [hbPesos(v.saldo + a.it), 'pagas en total por ' + hbPesos(v.saldo)]],
      graf: { tipo: 'linea', t: 'Lo que debes, mes a mes', fy: 'pesos', x, series: [{ n: 'Lo que debes', v: s }], area: true },
      nota: 'Con <b>$500 más al mes</b> terminas en ' + b.m + ' meses y te ahorras <b>' + hbPesos(a.it - b.it) + '</b> de intereses.' };
  },
  // Lo que ya pagas de MSI más la compra nueva, contra lo que te sobra para ahorrar.
  msi(v) {
    const total = v.ya + v.compra / v.n, pct = total / v.sobra * 100;
    return { cifras: [[hbPesos(total), 'al mes en MSI, con la compra nueva'], [Math.round(pct) + ' %', 'de lo que te sobra ya tiene dueño'], [v.n + ' meses', 'con ese dinero comprometido']],
      nota: pct >= 50 ? 'Más de la mitad de tu ahorro se va a meses sin intereses: <b>no firmes otro</b> hasta liberar alguno.' : pct >= 30 ? 'Una tercera parte de tu ahorro ya está comprometida. Si de todos modos la haces, <b>aparta el total desde el primer mes</b>.' : 'Cabe. Aun así, aparta el total desde el primer mes: así el MSI es una herramienta y no una trampa.' };
  },
  // Aportación mensual con rendimiento compuesto mensual: lo que juntas contra lo que pusiste.
  compuesto(v) {
    const r = v.tasa / 100 / 12, f = m => r ? v.aporte * ((Math.pow(1 + r, m) - 1) / r) : v.aporte * m, fv = f(v.anos * 12), puesto = v.aporte * v.anos * 12;
    const paso = Math.max(1, Math.ceil(v.anos / 12)), x = [], s1 = [], s2 = [];
    for (let a = 0; a <= v.anos; a += paso) { x.push(a === 0 ? 'Hoy' : a + (a === v.anos ? ' años' : '')); s1.push(Math.round(f(a * 12))); s2.push(v.aporte * a * 12); }
    if (v.anos % paso) { x.push(v.anos + ' años'); s1.push(Math.round(fv)); s2.push(puesto); }
    return { cifras: [[hbPesos(fv), 'juntas en ' + v.anos + ' años'], [hbPesos(puesto), 'lo que pusiste tú'], [Math.round((fv - puesto) / fv * 100) + ' %', 'lo puso el rendimiento']],
      graf: { tipo: 'linea', t: 'Lo que juntas contra lo que pusiste', fy: 'pesos', x, series: [{ n: 'Lo que juntas', v: s1 }, { n: 'Lo que pusiste', v: s2 }], area: true } };
  },
  // La comisión se resta del rendimiento cada año: lo que se lleva y qué parte de la ganancia es.
  comision(v) {
    const f = t => { const r = t / 100 / 12, n = v.anos * 12; return r ? v.aporte * ((Math.pow(1 + r, n) - 1) / r) : v.aporte * n; };
    const sin = f(v.tasa), con = f(v.tasa - v.com), puesto = v.aporte * v.anos * 12, pierde = sin - con, pct = sin > puesto ? pierde / (sin - puesto) * 100 : 0;
    return { cifras: [[hbPesos(pierde), 'se lleva la comisión en ' + v.anos + ' años'], [Math.round(pct) + ' %', 'de lo que habrías ganado'], [hbPesos(con), 'te queda, contra ' + hbPesos(sin) + ' sin comisión']],
      graf: { tipo: 'barras', datos: [['Sin comisión', sin, hbPesosCorto(sin)], ['Con ' + v.com.toLocaleString('es-MX') + ' % de comisión', con, hbPesosCorto(con)], ['Lo que pusiste tú', puesto, hbPesosCorto(puesto)]], dest: [1] } };
  }
};

/* Los números de Adán que una gráfica o una calculadora necesita como número, leídos del maestro y nunca copiados: sus horas
   de sueño y su hora de dormir salen de la rutina ({{horaDormir}} → {{horaDespertar}}). */
const HB_DATO = {
  dormir() { const p = CIFRAS.texto('{{horaDormir}}').split(':'); return +p[0] + p[1] / 60; },
  sueno() { const m = h => { const p = CIFRAS.texto(h).split(':'); return +p[0] * 60 + +p[1]; }; return ((m('{{horaDespertar}}') - m('{{horaDormir}}') + 1440) % 1440) / 60; }
};

if (typeof module !== 'undefined' && module.exports) module.exports = { HB_VISUAL, HB_CALC, HB_DATO };
